INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '4b418b24-bfd6-5123-a3e0-e6a1bcc89e65', 'ea203213-8586-52a7-8d09-1fde8583ed96',
  'Sort algorithms: which one is correct?

Lựa chọn:
- Selection Sort: The list is divided into two parts: sorted and unsorted. In each pass, in the unsorted sublist, the smallest element is selected and exchanged with the first element.
- Heap Sort: The unsorted sublist is organized into a heap. In each pass, in the unsorted sublist, the largest element is selected and exchanged with the last element. The heap is then reheaped.
- All the other answers are correct.
- Straight Insertion Sort: The list is divided into two parts: sorted and unsorted. In each pass, the first element of the unsorted sublist is inserted into the sorted sublist.', 3
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '63e39ef1-73b5-5518-a6b8-401f4812a8aa', 'ea203213-8586-52a7-8d09-1fde8583ed96',
  'Sort algorithms: which one is correct?

Lựa chọn:
- Quick sort: divide the list into smaller list and larger list, recursively sort the two list, and then merge them into one.
- Bubble sort: The list is divided into two parts: sorted and unsorted. In each pass, in the unsorted sublist, the smallest element is selected and exchanged with the first element.
- Merge sort: divide the list into the two half, sort the two lists, and merge them into one.
- All the other answers are correct.', 4
);

